function validate([nums, k]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each value is an integer from 1 to nums.length.';
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is an integer from 1 to nums.length.';
  return null;
}

