function kBigIndices(nums, k) {
  const n = nums.length;
  const left = new Array(n + 1).fill(0);
  const right = new Array(n + 1).fill(0);
  const add = (tree, value, delta) => {
    for (let i = value; i <= n; i += i & -i) {
      tree[i] += delta;
    }
  };
  const countBelow = (tree, value) => {
    let total = 0;
    for (let i = value - 1; i > 0; i -= i & -i) {
      total += tree[i];
    }
    return total;
  };
  for (const value of nums) {
    add(right, value, 1);
  }
  let answer = 0;
  for (const value of nums) {
    add(right, value, -1);
    if (countBelow(left, value) >= k && countBelow(right, value) >= k) {
      answer++;
    }
    add(left, value, 1);
  }
  return answer;
}

