function kBigIndices(nums, k) {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    let before = 0, after = 0;
    for (let j = 0; j < nums.length; j++) {
      if (nums[j] >= nums[i]) continue;
      if (j < i) before++;
      else after++;
    }
    if (before >= k && after >= k) count++;
  }
  return count;
}

