function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const top = rand() < 0.3 ? pick(1, 20) : n;
    const nums = Array.from({ length: n }, () => pick(1, top));
    const k = rand() < 0.5 ? pick(1, 50) : pick(1, Math.floor(n / 3));
    return [nums, k];
  }
  const n = pick(1, 10);
  const top = rand() < 0.3 ? Math.min(n, 3) : n;
  const nums = Array.from({ length: n }, () => pick(1, top));
  const k = rand() < 0.7 ? pick(1, Math.min(n, 3)) : pick(1, n);
  return [nums, k];
}
